   29          ArgumentException.ThrowIfNullOrWhiteSpace(identifier);
   30  
   31          // Remove any existing KQL bracket escape sequences to normalize the identifier
   32          var unescaped = identifier
   33              .Replace("['", "", StringComparison.Ordinal)
