   53  export const registerGZipFileAsResourceTool = (server) => {
   54      server.registerTool(name, config, async (args) => {
   55          const { name, data: dataUri, outputType, } = GZipFileAsResourceSchema.parse(args);
   56          // Validate data uri
   57          const url = validateDataURI(dataUri);
   58          // Fetch the data
   59          const response = await fetchSafely(url, {
   60              maxBytes: GZIP_MAX_FETCH_SIZE,
   61              timeoutMillis: GZIP_MAX_FETCH_TIME_MILLIS,
   62          });
   63          // Compress the data using gzip
   64          const inputBuffer = Buffer.from(response);
   65          const compressedBuffer = gzipSync(inputBuffer);
   66          // Create resource
   67          const uri = getSessionResourceURI(name);
   68          const blob = compressedBuffer.toString("base64");
   69          const mimeType = "application/gzip";
   70          const resource = { uri, name, mimeType };
   71          // Register resource, get resource link in return
   72          const resourceLink = registerSessionResource(server, resource, "blob", blob);
   73          // Return the resource or a resource link that can be used to access this resource later
   74          if (outputType === "resource") {
   75              return {
   76                  content: [
   77                      {
   78                          type: "resource",
   79                          resource: { uri, mimeType, blob },
   80                      },
   81                  ],
   82              };
   83          }
   84          else if (outputType === "resourceLink") {
   85              return {
   86                  content: [resourceLink],
   87              };
   88          }
   89          else {
   90              throw new Error(`Unknown outputType: ${outputType}`);
   91          }
   92      });
   93  };

