  197          // Include relations where at least one endpoint is in the requested set.
  198          // Previously this required BOTH endpoints, which meant relations from a
  199          // requested node to an unrequested node were silently dropped — making it
  200          // impossible to discover a node's connections without reading the full graph.
  201          const filteredRelations = graph.relations.filter(r => filteredEntityNames.has(r.from) || filteredEntityNames.has(r.to));
  202          const filteredGraph = {
  203              entities: filteredEntities,
  204              relations: filteredRelations,
  205          };
  206          return filteredGraph;
