  519  function formatPageAnalyzeResult(result, metadata) {
  520    if (result.elements && result.elements.length > 0) {
  521      const platformInfo = result.summary?.anti_detection_platform
  522        ? `\n🎯 Anti-detection platform detected: ${result.summary.anti_detection_platform}`
  523        : "";
  524  
  525      const summary =
  526        `Found ${result.elements.length} relevant elements using ${result.method}:${platformInfo}\n\n` +
  527        result.elements
  528          .map((el) => {
  529            // The discover phase emits type/ready/state at the top level; the
  530            // detailed phase emits a fingerprint and nests state under meta.
  531            const ready = el.ready ?? el.meta?.state?.interaction_ready;
  532            const disabled = el.state === "disabled" || el.meta?.state?.disabled;
  533            const type = el.type || el.fp || "element";
  534            const readyStatus = ready ? "✅ Ready" : "⚠️ Not ready";
  535            const stateInfo = disabled ? " (disabled)" : "";
  536            return `• ${el.name} (${type}) - Confidence: ${el.conf}% ${readyStatus}${stateInfo}\n  Element ID: ${el.id}`;
  537          })
  538          .join("\n\n");
  539      return `${summary}\n\n${JSON.stringify(metadata, null, 2)}`;
  540    } else {
  541      const intentHint = result.intent_hint || "unknown";
  542      const platformInfo = result.summary?.anti_detection_platform
  543        ? `\nPlatform: ${result.summary.anti_detection_platform}`
  544        : "";
  545      return `No relevant elements found for intent: "${intentHint}"${platformInfo}\n\n${JSON.stringify(
  546        metadata,
  547        null,
  548        2
  549      )}`;
  550    }
  551  }
