  581          const INITIAL_POLL_INTERVAL = 2000; // 2 seconds in ms
  582          const MAX_POLL_INTERVAL = 10000; // 10 seconds in ms
  583          const POLL_BACKOFF_FACTOR = 1.5;
  584          const MAX_PRO_MODEL_POLL_DURATION = 900000; // 15 minutes in ms
  585          const MAX_MINI_MODEL_POLL_DURATION = 300000; // 5 minutes in ms
  586          try {
  587              const response = await this.axiosInstance.post(this.baseURLs.research, {
  588                  input: params.input,
  589                  model: params.model || 'auto',
  590                  ...(IS_KEYLESS ? {} : { api_key: API_KEY })
  591              });
  592              const requestId = response.data.request_id;
  593              if (!requestId) {
  594                  return { error: `No request_id returned from research endpoint. Documentation: ${this.docsURLs.research}` };
  595              }
  596              // For model=auto, use pro timeout since we don't know which model will be used
  597              const maxPollDuration = params.model === 'mini'
  598                  ? MAX_MINI_MODEL_POLL_DURATION
  599                  : MAX_PRO_MODEL_POLL_DURATION;
  600              let pollInterval = INITIAL_POLL_INTERVAL;
  601              let totalElapsed = 0;
  602              while (totalElapsed < maxPollDuration) {
  603                  await new Promise(resolve => setTimeout(resolve, pollInterval));
  604                  totalElapsed += pollInterval;
  605                  try {
