  258  export async function handleWriteFile(args) {
  259      try {
  260          const modeProvided = !!(args && typeof args === 'object' && 'mode' in args);
  261          const parsed = WriteFileArgsSchema.parse(args);
  262          // An omitted `mode` falls back to 'rewrite', which silently destroys
  263          // the target's existing content. The common failure is an LLM caller
  264          // intending to append but dropping the optional param (issue #541), so
  265          // require explicit intent when the target already has content;
  266          // new/empty files keep the zero-friction default.
  267          if (!modeProvided) {
  268              let existing = null;
  269              try {
