  271              }
  272              catch {
  273                  // Missing file or invalid path — nothing to protect; the write
  274                  // itself will surface any real path error.
  275              }
  276              if (existing?.isFile && existing.size > 0) {
  277                  return createErrorResponse(`Write rejected to prevent accidental data loss: ${parsed.path} already exists ` +
